import NuevoRol from "../../../Componentes/Formularios/NuevoRol/NuevoRol";
import PestaniasConfiguraciones from "../../../Componentes/PestaniasConfiguraciones/PestaniasConfiguraciones";
import { useState, useEffect } from 'react';
import Boton from '../../../Componentes/Boton/Boton';
import Modal from '../../../Componentes/Modal/Modal';
import PlantillaConfiguraciones from '../../../Componentes/PlantillaConfiguraciones/PlantillaConfiguraciones';
import ojo from '../../../assets/ojo.png';
import mas from '../../../assets/mas.png';
import '../Proveedores/Proveedores.css';
import CheckBoxes from "../../../Componentes/CheckBoxes/CheckBoxes";
import { useValidarSesion } from "../../../hooks/useValidarSesion";

export default function Roles() {

    //Recupero informacion del usuario logueado
    const { usuario, token } = useValidarSesion(); // obtener el token desde Zustand

    //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE crear rol
    const permisoCrearRol = usuario?.permisos?.some(
        (permiso) => permiso.nombrePermiso === 'crear rol'
    ) ||
        usuario?.permisos_extra?.some(
            (permiso) => permiso.nombrePermiso === 'crear rol'
        );

    //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
    const transformaMayusucula = (str) => {
        if (!str || typeof str !== 'string') return '';
        return str.replace(/\b\w/g, (char) => char.toUpperCase());
    };


    ////////OBTENER LISTA DE ROLES
    const [roles, setRoles] = useState([]);
    const obtenerDatos = () => {
    fetch(`${import.meta.env.VITE_API_BASE_URL}/api/rol`)
            .then(respuesta => respuesta.json())
            .then(datos => setRoles(datos))
            .catch(e => console.log(e));
    }

    useEffect(() => {
        obtenerDatos();
    }, []);



    /////////MODAL NUEVO ROL

    const [modalNuevoRol, setModalNuevoRol] = useState(false);
    const manejaModalNuevoRol = () => {
        if (modalNuevoRol) {
            obtenerDatos();
        }
        setModalNuevoRol(!modalNuevoRol);
    };

    ////////MODAL VER ROL
    const [modalVerRol, setModalVerRol] = useState(false);
    const manejaModalVerRol = () => {
        setModalVerRol(!modalVerRol);
    };

    //////MANEJA SELECCION
    const [seleccionado, setSeleccionado] = useState('');
    ////////OBTENER LISTA DE PERMISOS de un ROL seleccionado
    const [permisosRol, setPermisosRol] = useState([]);
    const [todosPermisos, setTodosPermisos] = useState([]);

    // En la función manejaSeleccion, cambia esto:
    const manejaSeleccion = async ({ id_rol, nombre_rol }) => {
        setSeleccionado({ id_rol, nombre_rol });

        try {
            const [rolRespuesta, permisosRespuesta] = await Promise.all([
                fetch(`${import.meta.env.VITE_API_BASE_URL}/api/rol/${id_rol}`),
                fetch(`${import.meta.env.VITE_API_BASE_URL}/api/permiso`),
            ]);
            const rolData = await rolRespuesta.json();
            const permisosData = await permisosRespuesta.json();

            // Extraer los ids de los permisos del rol
            const idsPermisosRol = rolData.permisos.map((p) => p.id_permiso);

            setTodosPermisos(permisosData);
            setPermisosRol(idsPermisosRol);

        } catch (error) {
            console.error(error);
        }

        manejaModalVerRol(); // abre el modal
    };

    console.log(seleccionado);

    // Dividir permisos en columnas de 5
    const columnas = [];
    for (let i = 0; i < todosPermisos.length; i += 5) {
        columnas.push(todosPermisos.slice(i, i + 5));
    }

    /////////LAYOUT

    const navigation = <PestaniasConfiguraciones></PestaniasConfiguraciones>

    const main = <div className='__cuerpo_proveedores'>
        <div className='__cabecera_proveedores'>
            <h1>Roles</h1>
            {permisoCrearRol && <Boton icono={mas} habilitado onClick={manejaModalNuevoRol} title="Crear nuevo rol"></Boton>}
        </div>
        <div className='__lista_proveedores'>
            {roles.map((item, index) => (
                <div className="__proveedor_item" key={index}>
                    {permisoCrearRol ? <span className='__proveedor_categoria'>{transformaMayusucula(item.nombre_rol)}</span> :
                        <span className='__proveedor_categoria' style={{ padding: "10px" }}>{transformaMayusucula(item.nombre_rol)}</span>}
                    {permisoCrearRol && <Boton icono={ojo} habilitado onClick={() => manejaSeleccion({
                        id_rol: item.id_rol,
                        nombre_rol: item.nombre_rol
                    })} title="Ver rol"></Boton>}
                </div>

            ))}

        </div>
        <Modal visible={modalNuevoRol} funcion={manejaModalNuevoRol} titulo="Nuevo Rol" anchura="800px">
            <NuevoRol onGuardar={manejaModalNuevoRol} token={token}></NuevoRol>
        </Modal>
        <Modal visible={modalVerRol} funcion={manejaModalVerRol} titulo={transformaMayusucula(seleccionado?.nombre_rol)} anchura="800px">
            {columnas.length > 0 ? (
                <div className="__checkboxes_columnas">
                    {columnas.map((columna, i) => (
                        <div key={i} className="__columna_checkbox">
                            <CheckBoxes
                                opciones={columna.map(p => ({ id: p.id_permiso, nombre: p.nombre_permiso }))}
                                valoresSeleccionados={permisosRol} // ids de los permisos del rol
                                soloLectura={true}                 // solo lectura
                            />
                        </div>
                    ))}
                </div>
            ) : (
                <p>Cargando permisos...</p>
            )}
            <div style={{ display: 'flex', justifyContent: 'end', marginTop: '20px' }}>
                <Boton descripcion="Cerrar" habilitado onClick={manejaModalVerRol} ></Boton>
            </div>
        </Modal>


    </div>


    return <PlantillaConfiguraciones navigation={navigation} main={main} />;
}